<script>
  const fs=document.getElementById('fullscreen');
  const open=()=>fs.classList.add('show');
  const close=()=>fs.classList.remove('show');
  document.getElementById('trackOpen').onclick=open;
  document.getElementById('heroOpen').onclick=open;
  document.getElementById('close').onclick=close;
  let playing=false;
  function toggle(){
    playing=!playing;
    document.getElementById('topPlay').textContent=playing?'Ⅱ':'▶';
    document.getElementById('fullPlay').textContent=playing?'Ⅱ':'▶';
  }
  document.getElementById('topPlay').onclick=toggle;
  document.getElementById('fullPlay').onclick=toggle;
</script>
